/**
 * The animal library: ready-made, rigged and animated animals that are not generated by
 * Actors but loaded from glTF files (`loadLibraryAnimal` in `@actors/three`).
 *
 * This module is only the public catalogue (names and facts). The models themselves are
 * licensed for Arnd's projects only and live in the private repository
 * `ArndRosemeier/PrivateAssets` (folder `wildmesh3d/`). Never copy them into this repo,
 * a release or the GitHub Pages build. See docs/using-actors.md, "Library animals".
 */
import catalogue from "./library/wildmesh3d.json";

/** What kind of animal it is. */
export type LibraryGroup = "mammal" | "bird" | "reptile" | "fish" | "crustacean";

export interface LibraryClip {
  name: string;
  /** Length in seconds (0 for single-frame poses). */
  seconds: number;
  /** Animated channels (bone rotations, positions, scales). Far fewer than the animal's other clips = a partial clip (additive layer, face loop, or broken). */
  tracks: number;
}

export interface LibraryAnimalInfo {
  /** Folder and file name in the library: `<baseUrl>/<id>/<id>.glb`. */
  id: string;
  /** Display name, e.g. "African elephant". Several animals can share a name (realistic and stylized). */
  name: string;
  /** "realistic" (painted textures, many clips) or "stylized" (low poly, toon-like). */
  set: "realistic" | "stylized";
  group: LibraryGroup;
  /**
   * Rig family: animals of the same family have the same bone names, so their clips can be
   * played on each other (e.g. family A: wolf, fox, boar, deer, ...). Undefined = own rig.
   */
  rig?: string;
  /** Bind-pose size in meters: [width (x), height (y), length (z)]. The animal faces +Z. */
  size: [number, number, number];
  triangles: number;
  /** Size of the .glb in megabytes (textures included). */
  mb: number;
  clips: LibraryClip[];
}

type Row = { id: string; name: string; set: string; group: string; rig?: string; size: number[]; triangles: number; mb: number; clips: [string, number, number][] };

/** The WildMesh3D animals (100: 64 realistic, 36 stylized), sorted by id. */
export const LIBRARY_ANIMALS: readonly LibraryAnimalInfo[] = (catalogue as Row[]).map((r) => ({
  ...r,
  set: r.set as LibraryAnimalInfo["set"],
  group: r.group as LibraryGroup,
  size: r.size as [number, number, number],
  clips: r.clips.map(([name, seconds, tracks]) => ({ name, seconds, tracks })),
}));

/** The private repository that holds the models (clone it, or add it as a submodule or git dependency). */
export const LIBRARY_REPO = "https://github.com/ArndRosemeier/PrivateAssets";

/** Catalogue entry by id (throws for an unknown id, listing close matches). */
export function libraryAnimal(id: string): LibraryAnimalInfo {
  const found = LIBRARY_ANIMALS.find((a) => a.id === id);
  if (found) return found;
  const near = LIBRARY_ANIMALS.filter((a) => a.id.includes(id) || id.includes(a.id) || a.name.toLowerCase().includes(id.toLowerCase())).map((a) => a.id);
  throw new Error(`No library animal "${id}"${near.length ? ` (did you mean ${near.join(", ")}?)` : ""}`);
}

/**
 * Finds animals by a free-text query over id, name, group and set, e.g. `findLibraryAnimals("deer")`
 * or `findLibraryAnimals("bird stylized")`. Every word must match.
 */
export function findLibraryAnimals(query: string): LibraryAnimalInfo[] {
  const words = query.toLowerCase().split(/\s+/).filter(Boolean);
  return LIBRARY_ANIMALS.filter((a) => {
    const text = `${a.id} ${a.name} ${a.group} ${a.set}`.toLowerCase();
    return words.every((w) => text.includes(w));
  });
}

/**
 * Clip names of an animal that match a pattern, e.g. `libraryClips("wolf", /walk/i)`.
 * Clip names come from the pack and differ between rig families ("Walk_F_RM", "G0_Walk", "walk").
 */
export function libraryClips(id: string, pattern?: RegExp): string[] {
  const names = libraryAnimal(id).clips.map((c) => c.name);
  return pattern ? names.filter((n) => pattern.test(n)) : names;
}

export { pickLibraryClip, type LibraryMotion } from "@actors/core";
